def now_iso():
    return datetime.now().isoformat(timespec="seconds")


def get_connection():
    return get_afrisync_connection(SERVER_DATABASE)


def table_exists(cursor, table_name):
    return backend_table_exists(cursor, table_name)


def column_exists(cursor, table_name, column_name):
    if not table_exists(cursor, table_name):
        return False
    return backend_column_exists(cursor, table_name, column_name)


print(f"[AfriSync Admin] Database backend: {get_database_backend()}")


def add_column_if_missing(cursor, table_name, column_name, definition):
    if table_exists(cursor, table_name) and not column_exists(cursor, table_name, column_name):
        cursor.execute(f"ALTER TABLE {table_name} ADD COLUMN {column_name} {definition}")


def safe_count(cursor, table_name, where_clause="", params=()):
    if not table_exists(cursor, table_name):
        return 0
    sql = f"SELECT COUNT(*) AS total FROM {table_name} {where_clause}".strip()
    cursor.execute(sql, params)
    row = cursor.fetchone()
    return int(row["total"] if row else 0)


def safe_sum(cursor, table_name, column_name, where_clause="", params=()):
    if not table_exists(cursor, table_name):
        return 0
    sql = f"SELECT COALESCE(SUM({column_name}), 0) AS total FROM {table_name} {where_clause}".strip()
    cursor.execute(sql, params)
    row = cursor.fetchone()
    return int(row["total"] if row else 0)


def rows_to_dicts(rows):
    return [dict(row) for row in rows]


def initialize_admin_database():
    connection = get_connection()
    cursor = connection.cursor()

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS admin_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token_hash TEXT UNIQUE NOT NULL,
            csrf_hash TEXT NOT NULL,
            username TEXT NOT NULL,
            created_at TEXT NOT NULL,
            last_seen_at TEXT NOT NULL,
            expires_at TEXT NOT NULL
        )
        """
    )

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS admin_action_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action_uuid TEXT UNIQUE NOT NULL,
            admin_username TEXT NOT NULL,
            action_type TEXT NOT NULL,
            target_type TEXT NOT NULL,
            target_id TEXT,
            details TEXT,
            created_at TEXT NOT NULL
        )
        """
    )

    if table_exists(cursor, "users"):
        add_column_if_missing(cursor, "users", "email", "TEXT")
        add_column_if_missing(cursor, "users", "full_name", "TEXT")
        add_column_if_missing(cursor, "users", "email_verified", "INTEGER DEFAULT 1")
        add_column_if_missing(cursor, "users", "email_verified_at", "TEXT")
        add_column_if_missing(cursor, "users", "is_disabled", "INTEGER DEFAULT 0")
        add_column_if_missing(cursor, "users", "disabled_at", "TEXT")
        add_column_if_missing(cursor, "users", "disabled_reason", "TEXT")
        add_column_if_missing(cursor, "users", "updated_at", "TEXT")
        add_column_if_missing(cursor, "users", "password_updated_at", "TEXT")
        add_column_if_missing(cursor, "users", "google_sub", "TEXT")
        add_column_if_missing(cursor, "users", "auth_provider", "TEXT DEFAULT 'password'")
        add_column_if_missing(cursor, "users", "google_linked_at", "TEXT")
        add_column_if_missing(cursor, "users", "avatar_url", "TEXT")
        cursor.execute("UPDATE users SET is_disabled = 0 WHERE is_disabled IS NULL")
        cursor.execute("UPDATE users SET email_verified = 1 WHERE email_verified IS NULL")
        cursor.execute("UPDATE users SET auth_provider = COALESCE(auth_provider, 'password') WHERE auth_provider IS NULL OR auth_provider = ''")
        cursor.execute(
            "UPDATE users SET updated_at = COALESCE(updated_at, created_at, ?) WHERE updated_at IS NULL",
            (now_iso(),),
        )
        cursor.execute(
            "UPDATE users SET password_updated_at = COALESCE(password_updated_at, created_at, updated_at, ?) WHERE password_updated_at IS NULL",
            (now_iso(),),
        )

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS password_reset_tokens (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token_hash TEXT UNIQUE NOT NULL,
            user_id TEXT NOT NULL,
            username TEXT NOT NULL,
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            used_at TEXT
        )
        """
    )
    cursor.execute(
        "CREATE INDEX IF NOT EXISTS idx_admin_password_reset_user ON password_reset_tokens (user_id, used_at, expires_at)"
    )

    connection.commit()
    connection.close()


initialize_admin_database()


# ============================================================
# AUTH HELPERS
# ============================================================


def hash_value(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def create_password_reset_token(cursor, user_id, username):
    reset_token = secrets.token_urlsafe(36)
    now = datetime.now()
    expires_at = now + timedelta(seconds=PASSWORD_RESET_TTL_SECONDS)

    cursor.execute(
        "UPDATE password_reset_tokens SET used_at = ? WHERE user_id = ? AND used_at IS NULL",
        (now.isoformat(), user_id),
    )
    cursor.execute(
        "DELETE FROM password_reset_tokens WHERE expires_at <= ?",
        (now.isoformat(),),
    )
    cursor.execute(
        """
        INSERT INTO password_reset_tokens (
            token_hash, user_id, username, created_at, expires_at, used_at
        ) VALUES (?, ?, ?, ?, ?, NULL)
        """,
        (
            hash_value(reset_token),
            user_id,
            username,
            now.isoformat(),
            expires_at.isoformat(),
        ),
    )

    return reset_token, expires_at.isoformat()


def create_admin_session(username):
    token = secrets.token_urlsafe(48)
    csrf = secrets.token_urlsafe(32)
    now = datetime.now()
    expires = now + timedelta(hours=ADMIN_SESSION_HOURS)

    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute("DELETE FROM admin_sessions WHERE expires_at <= ?", (now.isoformat(),))
    cursor.execute(
        """
        INSERT INTO admin_sessions (
            token_hash, csrf_hash, username,
            created_at, last_seen_at, expires_at
        ) VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            hash_value(token),
            hash_value(csrf),
            username,
            now.isoformat(),
            now.isoformat(),
            expires.isoformat(),
        ),
    )
    connection.commit()
    connection.close()
    return token, csrf, expires


def get_admin_session(request: Request):
    token = request.cookies.get(ADMIN_SESSION_COOKIE)
    if not token:
        raise HTTPException(status_code=401, detail="Admin authentication required.")

    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute(
        """
        SELECT token_hash, csrf_hash, username, expires_at
        FROM admin_sessions
        WHERE token_hash = ?
        """,
        (hash_value(token),),
    )
    row = cursor.fetchone()

    if not row:
        connection.close()
        raise HTTPException(status_code=401, detail="Admin session is invalid.")

    now = datetime.now()
    try:
        expires = datetime.fromisoformat(row["expires_at"])
    except (TypeError, ValueError):
        expires = now - timedelta(seconds=1)

    if expires <= now:
        cursor.execute("DELETE FROM admin_sessions WHERE token_hash = ?", (hash_value(token),))
        connection.commit()
        connection.close()
        raise HTTPException(status_code=401, detail="Admin session has expired.")

    cursor.execute(
        "UPDATE admin_sessions SET last_seen_at = ? WHERE token_hash = ?",
        (now.isoformat(), hash_value(token)),
    )
    connection.commit()
    connection.close()

    return {"username": row["username"], "csrf_hash": row["csrf_hash"]}


def require_admin_csrf(request: Request, session):
    csrf = request.headers.get("X-CSRF-Token", "")
    if not csrf or not secrets.compare_digest(hash_value(csrf), session["csrf_hash"]):
        raise HTTPException(status_code=403, detail="Invalid admin CSRF token.")


def clear_admin_session(request: Request):
    token = request.cookies.get(ADMIN_SESSION_COOKIE)
    if not token:
        return
    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute("DELETE FROM admin_sessions WHERE token_hash = ?", (hash_value(token),))
    connection.commit()
    connection.close()


def log_admin_action(cursor, admin_username, action_type, target_type, target_id=None, details=None):
    cursor.execute(
        """
        INSERT INTO admin_action_logs (
            action_uuid, admin_username, action_type,
            target_type, target_id, details, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        (
            secrets.token_hex(16),
            admin_username,
            action_type,
            target_type,
            target_id,
            json.dumps(details or {}, ensure_ascii=False),
            now_iso(),
        ),
    )


