@app.get("/admin/api/health")
def admin_health(request: Request):
    get_admin_session(request)
    database_path = Path(SERVER_DATABASE)
    database_bytes = database_path.stat().st_size if database_path.exists() else 0

    upload_bytes = 0
    if SERVER_UPLOAD_ROOT.exists():
        for path in SERVER_UPLOAD_ROOT.rglob("*"):
            if path.is_file():
                try:
                    upload_bytes += path.stat().st_size
                except OSError:
                    pass

    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
    tables = [row["name"] for row in cursor.fetchall()]
    active_sessions = safe_count(cursor, "admin_sessions", "WHERE expires_at > ?", (datetime.now().isoformat(),))
    connection.close()

    return {
        "status": "online",
        "database_path": str(database_path.resolve()),
        "database_bytes": database_bytes,
        "upload_folder": str(SERVER_UPLOAD_ROOT.resolve()),
        "upload_bytes": upload_bytes,
        "admin_sessions_active": active_sessions,
        "tables": tables,
        "generated_at": now_iso(),
    }


