    connection = get_connection()
    cursor = connection.cursor()
    now = now_iso()
    cursor.execute(
        """
        UPDATE users
        SET is_disabled = 1,
            disabled_at = ?,
            disabled_reason = ?,
            updated_at = ?
        WHERE user_id = ?
        """,
        (now, reason, now, user_id),
    )
    if cursor.rowcount == 0:
        connection.close()
