@app.post("/admin/api/users/{user_id}/password-reset-token")
def generate_user_password_reset_token(user_id: str, request: Request):
    session = get_admin_session(request)
    require_admin_csrf(request, session)
    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute(
        """
        SELECT user_id, username, COALESCE(is_disabled, 0) AS is_disabled
        FROM users
        WHERE user_id = ?
        """,
        (user_id,),
    )
    user = cursor.fetchone()

    if not user:
        connection.close()
        raise HTTPException(status_code=404, detail="User not found.")

    if int(user["is_disabled"] or 0) == 1:
        connection.close()
        raise HTTPException(status_code=403, detail="Enable this user before generating a password reset token.")

    reset_token, expires_at = create_password_reset_token(
        cursor,
        user["user_id"],
        user["username"],
    )
    log_admin_action(
        cursor,
        session["username"],
        "GENERATE_PASSWORD_RESET",
        "user",
        user_id,
        {"username": user["username"], "expires_at": expires_at},
    )
    connection.commit()
    connection.close()

    return {
        "message": "Password reset token generated.",
        "user_id": user["user_id"],
        "username": user["username"],
        "development_reset_token": reset_token,
        "reset_token_expires_at": expires_at,
        "expires_in_minutes": int(PASSWORD_RESET_TTL_SECONDS / 60),
    }


