@app.post("/admin/api/projects/{project_uuid}/transfer-owner")
def transfer_project_owner(project_uuid: str, payload: TransferOwnerRequest, request: Request):
    session = get_admin_session(request)
    require_admin_csrf(request, session)
    new_owner_username = (payload.username or "").strip()
    if not new_owner_username:
        raise HTTPException(status_code=400, detail="New owner username is required.")

    connection = get_connection()
    cursor = connection.cursor()
    cursor.execute("SELECT user_id, username FROM users WHERE username = ?", (new_owner_username,))
    new_owner = cursor.fetchone()
    if not new_owner:
        connection.close()
        raise HTTPException(status_code=404, detail="New owner username was not found.")

    cursor.execute("SELECT project_uuid, user_id FROM projects WHERE project_uuid = ?", (project_uuid,))
    project = cursor.fetchone()
    if not project:
        connection.close()
        raise HTTPException(status_code=404, detail="Project not found.")

    old_owner_id = project["user_id"]
    new_owner_id = new_owner["user_id"]
    now = now_iso()

    if old_owner_id == new_owner_id:
        connection.close()
        raise HTTPException(status_code=400, detail="This user is already the owner.")

    cursor.execute(
        """
        UPDATE projects
        SET user_id = ?, version = COALESCE(version, 1) + 1, updated_at = ?
        WHERE project_uuid = ?
        """,
        (new_owner_id, now, project_uuid),
    )

    cursor.execute(
        """
        UPDATE project_members
        SET owner_user_id = ?, updated_at = ?
        WHERE project_uuid = ?
        """,
        (new_owner_id, now, project_uuid),
    )

    cursor.execute(
        """
        UPDATE project_members
        SET is_deleted = 1, updated_at = ?
        WHERE project_uuid = ? AND member_user_id = ?
        """,
        (now, project_uuid, new_owner_id),
    )

    cursor.execute(
        "SELECT username FROM users WHERE user_id = ?",
        (old_owner_id,),
    )
    old_owner = cursor.fetchone()
    old_owner_username = old_owner["username"] if old_owner else "previous_owner"

    cursor.execute(
        """
        INSERT INTO project_members (
            project_uuid, owner_user_id, member_user_id, member_username,
            role, is_deleted, invited_at, updated_at
        ) VALUES (?, ?, ?, ?, 'EDITOR', 0, ?, ?)
        ON CONFLICT(project_uuid, member_user_id) DO UPDATE SET
            owner_user_id = excluded.owner_user_id,
            member_username = excluded.member_username,
            role = 'EDITOR',
            is_deleted = 0,
            updated_at = excluded.updated_at
        """,
        (project_uuid, new_owner_id, old_owner_id, old_owner_username, now, now),
    )

    log_admin_action(
        cursor,
        session["username"],
        "TRANSFER_PROJECT_OWNER",
        "project",
        project_uuid,
        {"old_owner_id": old_owner_id, "new_owner_id": new_owner_id, "new_owner_username": new_owner["username"]},
    )
    connection.commit()
    connection.close()
    return {"message": "Project ownership transferred.", "project_uuid": project_uuid, "new_owner": new_owner["username"]}


