def build_csv_response(filename, rows):
    output = io.StringIO()
    if rows:
        writer = csv.DictWriter(output, fieldnames=list(rows[0].keys()))
        writer.writeheader()
        writer.writerows(rows)
    else:
        output.write("empty\n")
    return Response(
        content=output.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"},
    )


@app.get("/admin/api/export/{resource}")
def export_resource(resource: str, request: Request):
    get_admin_session(request)
    connection = get_connection()
    cursor = connection.cursor()
    resource = resource.lower().strip()
    allowed = {
        "users": "SELECT user_id, username, email, full_name, COALESCE(email_verified,1) AS email_verified, COALESCE(auth_provider,'password') AS auth_provider, CASE WHEN google_sub IS NOT NULL AND google_sub != '' THEN 1 ELSE 0 END AS google_linked, created_at, COALESCE(is_disabled,0) AS is_disabled, disabled_at, disabled_reason FROM users ORDER BY username COLLATE NOCASE",
        "projects": "SELECT project_uuid, user_id, name, location, progress, sync_status, is_deleted, deleted_at, version, updated_at FROM projects ORDER BY updated_at DESC",
        "members": "SELECT project_uuid, owner_user_id, member_user_id, member_username, role, is_deleted, invited_at, updated_at FROM project_members ORDER BY updated_at DESC",
        "notes": "SELECT note_uuid, project_uuid, user_id, SUBSTR(content,1,500) AS content_preview, sync_status, is_deleted, updated_at FROM project_notes ORDER BY updated_at DESC",
        "attachments": "SELECT attachment_uuid, project_uuid, user_id, original_file_name, file_type, file_size, sync_status, is_deleted, updated_at FROM project_attachments ORDER BY updated_at DESC",
        "audit": "SELECT action_uuid, admin_username, action_type, target_type, target_id, details, created_at FROM admin_action_logs ORDER BY id DESC",
    }
    if resource not in allowed:
        connection.close()
        raise HTTPException(status_code=404, detail="Export resource not found.")
    if not table_exists(cursor, resource if resource != "audit" else "admin_action_logs") and resource not in {"users", "projects"}:
        rows = []
    else:
        cursor.execute(allowed[resource])
        rows = rows_to_dicts(cursor.fetchall())
    connection.close()
    return build_csv_response(f"afrisync_{resource}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv", rows)


